def _crash(kind, value, tb):  # an unexpected crash exits 2, never 1 ("reproduced")
    import traceback

    traceback.print_exception(kind, value, tb)
    sys.stdout.flush()
    sys.stderr.flush()
    import os

    os._exit(2)


sys.excepthook = _crash

# torchcp imports torchsort / torch_geometric / transformers at module level; serve inert
# placeholders for any that are missing (they are never used here).
import importlib.abc, importlib.machinery, importlib.util, types  # noqa: E401


class _Stub(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    roots = [r for r in ("torchsort", "torch_geometric", "transformers")
             if importlib.util.find_spec(r) is None]

    def find_spec(self, name, path=None, target=None):
        if name.split(".")[0] in self.roots:
            return importlib.machinery.ModuleSpec(name, self, is_package=True)
        return None

    def create_module(self, spec):
        m = types.ModuleType(spec.name)
        m.__path__ = []

        def __getattr__(attr):
            if attr.startswith("__"):
                raise AttributeError(attr)
            return type(attr, (), {})

        m.__getattr__ = __getattr__
        return m

    def exec_module(self, module):
        pass


sys.meta_path.append(_Stub())

from sklearn.base import BaseEstimator, ClassifierMixin, RegressorMixin


class FixedRegressor(RegressorMixin, BaseEstimator):
    """A fixed, already fitted function: 2 x0 + shift."""

    def __init__(self, shift=0.3):
        self.shift = shift
        self.n_features_in_ = 2
        self.is_fitted_ = True

    def fit(self, X, y=None):
        return self

    def predict(self, X):
        return 2.0 * np.asarray(X, dtype=float)[:, 0] + self.shift


class FixedClassifier(ClassifierMixin, BaseEstimator):
    """Fixed linear-softmax classifier over 4 classes, temperature 2."""

    W = np.array([[2.0, -1.0, 0.5, -1.5], [-1.0, 2.0, 0.5, -0.5]])

    def __init__(self):
        self.classes_ = np.arange(4)
        self.n_features_in_ = 2
        self.is_fitted_ = True

    def fit(self, X, y=None):
        return self

    def predict_proba(self, X):
        z = np.asarray(X, dtype=float) @ self.W / 2.0
        e = np.exp(z - z.max(axis=1, keepdims=True))
        return e / e.sum(axis=1, keepdims=True)

    def predict(self, X):
        return self.predict_proba(X).argmax(axis=1)


class ZeroRegressor(RegressorMixin, BaseEstimator):
    """Ignores its training data and predicts 0: every leave-one-out or out-of-fold
    model is the same, so jackknife+ and CV+ reduce to split conformal on all n points
    with scores |y|, and the order statistic used can be read off the interval."""

    def fit(self, X, y=None):
        self.n_features_in_ = np.asarray(X).shape[1]
        return self

    def predict(self, X):
        return np.zeros(len(X))


QUANTILE_MODELS = [FixedRegressor(-1.3), FixedRegressor(1.9), FixedRegressor(0.3)]  # lo hi med

MEANS = np.array([[0.0, 0.0], [2.0, 0.0], [0.0, 2.0], [2.0, 2.0]])


def reg_data(rng, n):
    x = rng.uniform(size=(n, 2))
    return x, 2.0 * x[:, 0] + rng.normal(size=n)


def cls_data(rng, n, per_class=False):
    y = np.repeat(np.arange(4), n // 4) if per_class else rng.integers(0, 4, size=n)
    rng.shuffle(y)
    return MEANS[y] + rng.normal(size=(len(y), 2)), y

import torch
from torch.utils.data import DataLoader, TensorDataset
from torchcp.regression.predictor import SplitPredictor
from torchcp.regression.score import ABS
LIB = "torchcp"
class Identity(torch.nn.Module):
    def forward(self, x):
        return x
def intervals(x_cal, y_cal, x_test, alpha):
    f = lambda x: torch.tensor(MODEL.predict(x), dtype=torch.float32)[:, None]
    ds = TensorDataset(f(x_cal), torch.tensor(y_cal, dtype=torch.float32))
    p = SplitPredictor(score_function=ABS(), model=Identity(), device="cpu")
    p.calibrate(DataLoader(ds, batch_size=len(y_cal)), alpha=float(alpha))
    return p.predict(f(x_test)).numpy().reshape(len(x_test), -1, 2)[:, 0, :].astype(float)

MODEL = FixedRegressor()
N, ALPHA = 5, Fraction("1/10")
K = math.ceil((N + 1) * (1 - ALPHA))
print(f"{LIB} {version(LIB)}, numpy {np.__version__}")
print(f"n={N}, alpha={ALPHA} (passed as {float(ALPHA)!r}): k={K} "
      f"{'> n: a trivial set is required' if K > N else '<= n: a finite valid set exists'}")
# some failures depend on the calibration draw (e.g. a class missing): try 50 seeds
for seed in range(50):
    rng = np.random.default_rng(seed)
    try:
        x_cal, y_cal = reg_data(rng, N)
        x_test, _ = reg_data(rng, 3)
        intervals(x_cal, y_cal, x_test, ALPHA)
    except Exception as exc:
        print(f"seed {seed}: raised {type(exc).__name__}: {exc}")
        print("REPRODUCED")
        sys.exit(1)
print("returned normally for seeds 0-49")
sys.exit(0)
